    districts = [
        (1, 1, 'Ernakulam', 'ernakulam', 'A starting point for Kochi’s maritime heritage and coastal communities.', 'Try puttu with kadala curry and Kerala-style meals.', 'https://ernakulam.nic.in/'),
        (2, 1, 'Alappuzha', 'alappuzha', 'Slow down beside canals, backwaters and the Arabian Sea.', 'Look for appam, vegetable stew and local rice dishes.', 'https://alappuzha.nic.in/'),
        (3, 2, 'Jaipur', 'jaipur', 'Discover the Pink City’s architecture, observatory and nearby hill forts.', 'Try dal baati churma, ghewar and regional thalis.', 'https://www.tourism.rajasthan.gov.in/jaipur.html'),
        (4, 2, 'Jaisalmer', 'jaisalmer', 'A living sandstone fort city at the edge of the Thar Desert.', 'Try ker sangri, bajra roti and local sweets.', 'https://www.tourism.rajasthan.gov.in/jaisalmer.html'),
        (5, 3, 'North Goa', 'north-goa', 'Goa’s vibrant northern district encompasses the state capital Panaji, the historic Latin Quarter of Fontainhas, the UNESCO World Heritage monuments of Old Goa, and a world-renowned coastline from Candolim and Calangute to Anjuna, Vagator, and the serene beaches of Morjim and Arambol. North Goa is defined by dramatic red-laterite sea forts like Fort Aguada and Chapora Fort, 16th-century Portuguese-Manueline cathedrals, mangrove estuarine sanctuaries along the Mandovi River, bustling night markets, and an energetic coastal arts and music scene.', 'Indulge in authentic Goan coastal fare: prawn and fish curry rice with crispy rava-fried kingfish, pork vindaloo (slow-cooked with coconut vinegar, garlic and Kashmiri chillies), chicken cafreal (marinated in coriander, green chillies and whole spices), choris pav (spiced Goan pork sausage stuffed in warm crusty poi bread), crab xacuti with roasted coconut, and traditional multi-layered bebinca and serradura for dessert. Don’t miss freshly tapped cashew urrak and feni during spring.', 'https://www.goa-tourism.com/'),
        (6, 3, 'South Goa', 'south-goa', 'Quieter, greener, and culturally profound, South Goa stretches from the historic commercial hub of Margao and the peaceful coastal villages of Colva, Benaulim, Cavelossim, and Agonda down to the iconic crescent of Palolem Beach and the secluded coves of Canacona. Inland, the district shelters the lush Western Ghats of Bhagwan Mahaveer Sanctuary, the four-tiered cascade of Dudhsagar Falls, 17th-century aristocratic Indo-Portuguese palacios in Chandor and Quepem, and the sacred temple heartland of Ponda home to ancient shrines like Shree Manguesh and Shanta Durga.', 'Explore rich Saraswat Hindu and Catholic culinary traditions: authentic South Goan fish thali with kismoor (dried prawn coconut relish), prawn balchão (tangy-sweet fiery pickle curry), crab xec xec (rich roasted-coconut crab gravy), ambot tik (sour and spicy shark curry), freshly baked village poi and unndo from local padeiros, sol kadhi (kokum and coconut milk digestive), and alle belle (Goan coconut and jaggery crepes).', 'https://www.goa-tourism.com/'),
        (7, 4, 'Shimla', 'shimla', 'The historic summer capital of British India, Shimla is perched along a high mountain ridge surrounded by rhododendron, oak and deodar forests. Famous for the bustling pedestrian Mall Road, the broad hilltop promenade of The Ridge, Tudor-baronial Viceregal Lodge, the sacred hilltop Jakhu Temple, and the UNESCO-inscribed Kalka-Shimla mountain railway route.', 'Savour authentic Pahari delicacies: warm steaming Siddu served with fragrant ghee and dal, Sepu Badi in curd gravy, Chha Gosht, traditional Himachali Dham, freshly baked goods from heritage bakeries on Mall Road, and local apple preserves.', 'https://himachaltourism.gov.in/destination/shimla/'),
        (8, 4, 'Kangra', 'kangra', 'A magnificent valley cradled by the jagged Dhauladhar range, Kangra is a landscape of ancient temples, lush tea gardens, and vibrant spiritual cultures. Home to Dharamshala and McLeod Ganj (the exile residence of the Dalai Lama), the 8th-century monolithic rock-cut temples of Masroor, the thousand-year-old Kangra Fort overlooking the Banganga River, and the sacred Chamunda Devi shrine.', 'Indulge in authentic Kangri Dham: slow-cooked Madra (chickpeas in spiced yogurt gravy), Telia Maah (black lentils slow-cooked with mustard oil and whole spices), tangy Khatta pumpkin, sweet meethe bhat, and aromatic freshly brewed Kangra green and orthodox black teas.', 'https://himachaltourism.gov.in/destination/kangra/'),
        (9, 5, 'Chennai', 'chennai', 'A coastal city of music, temples, food and neighbourhood histories.', 'Try idli, dosa, filter coffee and seasonal local dishes.', 'https://www.tamilnadutourism.com/'),
        (10, 5, 'Madurai', 'madurai', 'A temple city shaped by ritual, markets, architecture and long food traditions.', 'Try jigarthanda, parotta and a Madurai-style meal.', 'https://www.tamilnadutourism.com/'),
        (11, 14, 'Bengaluru Urban', 'bengaluru-urban', 'A city district where technology, public parks, food and layered neighbourhoods meet.', 'Try local darshini breakfasts, filter coffee and regional meals.', 'https://karnatakatourism.org/'),
        (12, 14, 'Mysuru', 'mysuru', 'A palace city with markets, gardens and a strong cultural calendar.', 'Try Mysuru pak, dosas and local Karnataka meals.', 'https://karnatakatourism.org/'),
        (13, 16, 'Mumbai', 'mumbai', 'A dense island-city district of waterfronts, markets, food and historic architecture. The city blends Koli fishing traditions, Victorian gothic buildings, art deco boulevards and Irani café culture.', 'Try vada pav, coastal seafood and Irani café traditions.', 'https://aai-portal.maharashtratourism.gov.in/'),
        (14, 16, 'Pune', 'pune', 'A cultural and educational city with forts and food traditions nearby.', 'Try misal, bhakri and seasonal Maharashtrian dishes.', 'https://aai-portal.maharashtratourism.gov.in/'),
        (15, 26, 'Agra', 'agra', 'A historic city shaped by Mughal architecture, river landscapes and craft markets.', 'Try petha, Mughlai dishes and local street food.', 'https://www.uptourism.gov.in/'),
        (16, 26, 'Varanasi', 'varanasi', 'A river city of ghats, music, craft and pilgrimage traditions.', 'Try kachori-sabzi, local sweets and seasonal drinks.', 'https://www.uptourism.gov.in/'),
        (17, 28, 'Kolkata', 'kolkata', 'A cultural capital of books, theatre, colonial-era streets and Bengali food.', 'Try mishti doi, fish preparations and Kolkata street food.', 'https://wbtourism.gov.in/'),
        (18, 28, 'Darjeeling', 'darjeeling', 'A hill town of tea gardens, mountain views and railway heritage.', 'Try Darjeeling tea, momos and local bakery cafés.', 'https://wbtourism.gov.in/'),
        (19, 27, 'Dehradun', 'dehradun', 'A valley city connecting the foothills, institutions and routes toward the hills.', 'Try local bakery treats, garhwali dishes and seasonal fruits.', 'https://uttarakhandtourism.gov.in/'),
        (20, 27, 'Nainital', 'nainital', 'A lakeside town framed by forested ridges and mountain views.', 'Try bal mithai, ras and kumaoni food in town markets.', 'https://uttarakhandtourism.gov.in/'),
        (21, 32, 'New Delhi', 'new-delhi', 'The ceremonial and institutional capital, home to museums, gardens, street life and monument complexes.', 'Try chaat, Mughlai dishes, parathas and regional cooking from across the country.', 'https://delhitourism.gov.in/'),
        (22, 33, 'Srinagar', 'srinagar', 'A city shaped by Dal Lake, Mughal gardens, wooden architecture and living craft traditions.', 'Try wazwan, kahwa and local bakery breads.', 'https://jammutourism.jk.gov.in/'),
        (23, 33, 'Jammu', 'jammu', 'The winter hub and city of temples set beside the Tawi river, connecting the plains with the Pir Panjal range.', 'Try rajma chawal, kaladi cheese and local sweets.', 'https://jammutourism.jk.gov.in/'),
        (24, 34, 'Leh', 'leh', 'A high-altitude town and base for monastery, valley and mountain journeys. Leh sits at 3500 m and is the gateway to Pangong Lake, Nubra Valley and the Khardung La pass.', 'Try skyu, thukpa and locally grown apricots in season.', 'https://ladakh.gov.in/tourism/'),
        (25, 36, 'Puducherry', 'puducherry-district', 'A coastal town with French-era streetscapes, Tamil quarters, beaches and quiet courtyards.', 'Try French-influenced bakery items, coastal seafood and south Indian filter coffee.', 'https://tourism.py.gov.in/'),
        (26, 30, 'Chandigarh', 'chandigarh-district', 'A union territory and planned city of gardens, architecture and public art.', 'Try Punjabi and North Indian food across the city\'s sectors.', 'https://chandigarhtourism.gov.in/'),
        (27, 21, 'Puri', 'puri', 'Home to the sacred Shree Jagannath Temple, the ancient Sun Temple at nearby Konark, and sweeping Bay of Bengal beaches. One of India’s four holy Char Dham pilgrimage sites, famous worldwide for the grand Rath Yatra.', 'Taste Mahaprasad from the Jagannath Temple’s Anand Bazar (dalma, kanika rice, besara), crisp Puri khaja, rasabali, and fresh coastal seafood.', 'https://odishatourism.gov.in/content/tourism/en/discover/districts/puri.html'),
        (28, 21, 'Khordha', 'khordha', 'Encompassing Bhubaneswar—the City of Temples—with over 500 historic shrines including Lingaraj and Mukteshwar, alongside the ancient rock-cut caves of Udayagiri & Khandagiri and Ashoka’s edicts at Dhauli Hill.', 'Savour authentic Odia cuisine: dalma, pakhala bhata with badi chura, chhena poda (baked cheese cake), rasagola, and street delicacies.', 'https://odishatourism.gov.in/content/tourism/en/discover/districts/khurdha.html'),
        (29, 23, 'Gangtok', 'gangtok', 'Surrounding the capital town on a forested Himalayan ridge, Gangtok district is the cultural and administrative hub of Sikkim. Known for sweeping views of Mount Kangchenjunga, the Namgyal Institute of Tibetology, bustling MG Marg, Enchey Monastery, and the sacred high-altitude alpine lake of Tsomgo leading to the historic Silk Route at Nathu La.', 'Try authentic steamed momos with fiery dalle khursani chili paste, hearty thukpa noodle soup, sha phaley (crispy beef or chicken stuffed pastry), fermented gundruk jhol, chhurpi soup with fiddlehead ferns (ningro), and warming tongba (fermented millet beer in wooden casks).', 'https://www.sikkimtourism.gov.in/'),
        (30, 23, 'Gyalshing', 'gyalshing', 'The historical and spiritual cradle of Sikkim where the first Chogyal was crowned at Yuksom in 1642. Gyalshing is home to Pemayangtse Monastery (premier seat of the Nyingma order), the ancient royal stone palace ruins of Rabdentse, the sacred wish-fulfilling Khecheopalri Lake, and the dizzying Singshore Bridge. It is also the gateway for the legendary Goecha La trek toward Kangchenjunga.', 'Savour traditional Bhutia and Lepcha delicacies: buckwheat pancakes, ningro chhurpi (wild fiddlehead ferns cooked with indigenous cottage cheese), sinki soup, kinema (fermented soybean curry), and country chicken curry infused with timur (Himalayan Sichuan pepper).', 'https://www.sikkimtourism.gov.in/'),
        (31, 23, 'Mangan', 'mangan', 'Sikkim’s largest district by area, spanning monumental Himalayan landscapes from sub-tropical river gorges to arctic glacial summits. Mangan encompasses the breathtaking Yumthang Valley of Flowers, natural thermal springs, the high-altitude tribal villages of Lachen and Lachung, and the sacred glacial waters of Gurudongmar Lake at 5,430 metres near the Tibetan frontier. It also holds the core wilderness of Khangchendzonga National Park.', 'Enjoy robust high-altitude mountain meals: hot bowls of thenthuk (hand-pulled square pasta in rich broth), gyathuk, dried yak cheese (chhurpi), salted Tibetan butter tea (po cha), tsampa (roasted barley flour porridge), and momos with hot broth.', 'https://www.sikkimtourism.gov.in/'),
        (32, 23, 'Namchi', 'namchi', 'The cultural and pilgrimage heartland of southern Sikkim, set against rolling hills and tea gardens. Renowned for Siddhesvara Dhaam at Solophok (featuring a 108-foot statue of Lord Shiva and replicas of India’s four holy Char Dham shrines), Samdruptse Hill with its 138-foot gilded statue of Guru Padmasambhava, Ngadak Monastery, and Temi Tea Estate—Sikkim’s only tea garden producing prize-winning organic orthodox teas.', 'Sip fresh organic Temi black tea paired with golden sel roti (crisp Nepali rice doughnuts), spicy aloo dum in sesame gravy, sisnu (wild stinging nettle soup rich in iron), fermented kinema with rice, and momos accompanied by fresh tomato-dalle chutney.', 'https://www.sikkimtourism.gov.in/'),
        (33, 23, 'Pakyong', 'pakyong', 'A verdant eastern district hosting Sikkim’s greenfield airport perched atop mountain terraces. Home to the world-renowned Rumtek Monastery (Dharma Chakra Centre), the sacred 16th-century seat of the Gyalwang Karmapa. Pakyong also encompasses the peaceful hamlet of Aritar with its boot-shaped Lampokhari Lake, lush orchid cultivation centers, and the dramatic zigzag loops of the Old Silk Route at Zuluk.', 'Indulge in organic village thalis: dal bhat tarkari with seasonal wild mushrooms, smoked pork stir-fried with tender bamboo shoots, fermented mustard greens (gundruk), phagshapa (pork stewed with radishes and dried chillies), and festive sweet khapse pastries.', 'https://www.sikkimtourism.gov.in/'),
        (34, 23, 'Soreng', 'soreng', 'A tranquil southwestern district blessed with close-up panoramas of Mount Kangchenjunga and lush forest ridges. Soreng is celebrated for the Barsey Rhododendron Sanctuary, where dense canopy forests blaze with over 40 species of blooming rhododendrons in spring. Also known for Jorethang town along the Rangeet River, Chakung viewpoint, and peaceful eco-villages pioneering organic agriculture and community homestays.', 'Experience true farm-to-table village food: wholesome millet rotis (kodo ko roti) with fresh churned cow butter, stinging nettle broth (sisnu ko jhol), wild forest ferns with churpi, spicy radish gorkhali achar, and wild mountain berry fruit wines.', 'https://www.sikkimtourism.gov.in/'),
        (35, 25, 'West Tripura', 'west-tripura', 'Anchored by the capital city of Agartala, West Tripura is the royal, administrative and cultural heart of the state. It is celebrated for the majestic neoclassical Ujjayanta Palace set amidst Mughal-style formal gardens, the sacred temple of Chaturdash Devata at Old Agartala (famed for the annual Kharchi Puja), the serene lakeside sanctuary of Heritage Park, and the bustling Akhaura border crossing connecting India and Bangladesh.', 'Relish authentic Mui Borok and Bengali specialties: steaming Bangui rice (sun-dried aromatic sticky rice wrapped in Lairu leaves), spicy Wahan Mosdeng (roasted pork salad with green chillies, ginger, and coriander), Berma-based curries, crispy fish fry from Agartala markets, and sweet rasagolas and chamcham from traditional sweetmakers.', 'https://tripuratourism.gov.in/'),
        (36, 25, 'Gomati', 'gomati', 'The sacred temple capital of Tripura, named after the holy Gomati River that flows through it. Known historically as Udaipur, it is home to the 500-year-old Tripura Sundari Temple (Matabari)—one of India\'s 51 sacred Shakti Peethas—and its holy Kalyan Sagar lake with giant freshwater turtles. Upstream along the river gorge lies Chabimura (Chakhwtrakma), where massive 15th-century rock-cut carvings of Goddess Durga and Shiva are sculpted directly onto vertical sandstone cliffs rising from the river.', 'Taste famous Matabari peda (golden milk sweet offered as prasad), Chakhwi (traditional pork or fresh river fish stewed with bamboo shoots, jackfruit seeds, and indigenous alkaline herb water), fresh roasted river fish (Awandru), and spicy fermented fish chutney (Mosdeng Serma).', 'https://tripuratourism.gov.in/'),
        (37, 25, 'Sepahijala', 'sepahijala', 'A rich biodiversity and heritage district south of Agartala. Its crowning jewel is Neermahal (\'Water Palace\') at Melaghar, the only lake palace in Eastern India, constructed in 1930 by Maharaja Bir Bikram Kishore Manikya in the center of the vast Rudrasagar Lake (a Ramsar wetland). The district also shelters the Sepahijala Wildlife Sanctuary and Clouded Leopard National Park, famous for its captive breeding program of the rare clouded leopard and spectacled langurs.', 'Enjoy freshly caught Rudrasagar lake carp curry in mustard gravy, Gudok (traditional mashed dish of fermented fish, string beans, boiled potatoes, and wild greens served in bamboo hollows), bamboo-shoot pork stir-fry, and sweet local papayas and pineapples.', 'https://tripuratourism.gov.in/'),
        (38, 25, 'Unakoti', 'unakoti', 'Famous worldwide for its ancient rock-cut pilgrimage sanctuary carved into a lush forested gorge, dating from the 7th to 9th centuries. Meaning \'one less than a crore\' (99,99,999), the site features monumental Shaivite rock reliefs including the 30-foot head of Unakotiswara Kal Bhairava, gigantic Ganesha figures, and mountain springs. The district headquarters at Kailashahar is an ancient royal seat bordered by rolling tea gardens and the Manu River.', 'Sample authentic indigenous North Tripuri fare: Muya Awandru (tender bamboo shoot gravy with local rice flour), smoked river prawn salad with roasted garlic and green chillies, steamed sticky rice, and wild citrus and elephant apple (chalta) chutneys.', 'https://tripuratourism.gov.in/'),
        (39, 25, 'North Tripura', 'north-tripura', 'Encompassing the dramatic Jampui Hills range (rising to 3,200 ft at Betlingchhip peak) along the Mizoram border, celebrated as the \'Land of Eternal Spring\' for its cool climate, fragrant orange groves, and peaceful Mizo tribal hamlets such as Vanghmun. The district headquarters at Dharmanagar is a historic gateway town known for tea plantations, historic Kali temples, and scenic river valleys.', 'Enjoy fresh sweet Jampui oranges in season, traditional Mizo and Tripuri fusion meals: Bai (boiled pork or chicken with local greens, bamboo shoots and green chillies), roasted corn, spicy sesame and fermented fish chutneys, and freshly prepared local bamboo shoot curries.', 'https://tripuratourism.gov.in/'),
        (40, 25, 'South Tripura', 'south-tripura', 'Steeped in ancient archaeology and natural sanctuaries, South Tripura borders Bangladesh on three sides. It is internationally known for the Pilak Archaeological Site at Jolaibari, where 8th–12th century Buddhist stupas, terracotta plaques, and colossal stone sculptures of Avalokiteshvara and Surya illustrate a golden age of Hindu-Buddhist harmony. The district also encompasses Trishna Wildlife Sanctuary, a premier natural habitat of the Indian Gaur (bison).', 'Taste authentic southern Tripura rural delicacies: Chakhwi made with green papaya and dried fish, spicy crab curry cooked in mustard paste, country chicken with crushed wild pepper, and sweet pithe-puli rice cakes prepared during harvest celebrations.', 'https://tripuratourism.gov.in/'),
        (41, 25, 'Dhalai', 'dhalai', 'A verdant central highland district of dense forests, mountain ranges, and water bodies. Dhalai is famous for the vast Dumboor Lake—a 41 sq km reservoir dotted with 48 emerald-green hillock islands where the Raima and Sarma rivers meet. At Tirthamukh, the holy confluence hosts the ancient Pous Sankranti fair. The district is also known for producing Tripura\'s famous GI-tagged Queen Pineapple in the fertile valleys of Kamalpur.', 'Taste the world-famous sweet and aromatic Queen Pineapple fresh from the orchard, river fish curry with wild ferns (dhekia saak), mashed fermented fish chutney (Mosdeng), boiled taro root with green chillies, and aromatic sticky rice cakes.', 'https://tripuratourism.gov.in/'),
        (42, 25, 'Khowai', 'khowai', 'Named after the picturesque Khowai River, this district features rolling tea garden hills, tribal art settlements, and the lush Baramura Eco Park (Hathai Kotor) nestled in the Boromura mountain range. Khowai is a vibrant center for traditional bamboo and cane handicraft artisans and preserves peaceful rural landscapes ideal for eco-tourism and nature walks.', 'Enjoy fresh river fish curries with mustard oil and turmeric, boiled seasonal wild vegetables with berma, spicy mashed potato and dried fish bharta, crisp banana flower fritters, and sweet regional jaggery sweets.', 'https://tripuratourism.gov.in/'),
        (43, 4, 'Kullu', 'kullu', 'Famed as the "Valley of the Gods", Kullu spans the emerald Beas River valley framed by pine and deodar forests, apple orchards, and snow-crested Himalayan peaks. Home to the legendary resort town of Manali, the ancient 1553 AD pagoda-style wooden Hidimba Devi Temple, Naggar Castle, Solang Valley adventure slopes, and the majestic Rohtang Pass (3,978 m) leading into Lahaul.', 'Delight in authentic Kullu mountain cuisine: warm steamed Siddu (yeasted wheat flour dough stuffed with spiced crushed walnuts, poppy seeds, and paneer, soaked in desi ghee), fresh Himalayan river trout fried in butter and herbs, Khatta (tangy pumpkin preparation with dry mango powder), and festive Babru (stuffed kachori with black gram paste).', 'https://himachaltourism.gov.in/destination/kullu/'),
        (44, 4, 'Lahaul and Spiti', 'lahaul-and-spiti', 'A high-altitude Himalayan district of raw trans-Himalayan wilderness, ancient Buddhist monasteries, and jagged glaciated massifs. The Lahaul valley centers around Keylong along the Bhaga River, featuring the ancient Shashur and Kardang monasteries. Beyond the Atal Tunnel and Kunzum Pass (4,590 m) lies Spiti, a high-altitude cold desert sheltering thousand-year-old Buddhist monasteries and sapphire lakes.', 'Savour hearty high-altitude Tibetan and Lahauli winter dishes: steaming bowls of Thukpa (hand-pulled noodle soup with mountain greens), Tsampa (roasted highland barley flour mixed with warm butter tea), dried yak cheese (chhurpi), momos with fiery chutney, and local seabuckthorn berry tea.', 'https://himachaltourism.gov.in/destination/lahaul-spiti/'),
        (45, 4, 'Spiti', 'spiti', 'A cold desert mountain valley sitting high in the trans-Himalaya, Spiti ("The Middle Land" between India and Tibet) is a realm of stark moonscapes and ancient spiritual fortitude. Perched on sheer cliffs at 4,166 m is the dramatic 1,000-year-old Key Monastery; further down the valley sits Tabo Monastery ("Ajanta of the Himalayas", founded in 996 AD with ancient mud murals). The district is also home to the crescent-shaped turquoise glacial waters of Chandratal Lake at 4,250 m.', 'Warm up with traditional Spitian high-mountain cuisine: steaming Thenthuk (hand-pulled square pasta in savory vegetable or mutton broth), hot yak cheese soup, butter tea (po cha), barley cakes, fresh momos, and vitamin-rich wild seabuckthorn tea.', 'https://himachaltourism.gov.in/'),
        (46, 4, 'Chamba', 'chamba', 'A timeless valley district nestled on the banks of the Ravi River, Chamba is famed for its 10th-century wooden temples of Bharmaur, Chamba rumal embroidery, and the idyllic alpine meadow of Khajjiar ("Mini Switzerland of India"). The town of Chamba features the ancient Lakshmi Narayan temple complex and the Akhand Chandi Palace overlooking the Chaugan promenade.', 'Experience the royal Chamba Dham: authentic Madra (slow-cooked chickpeas or kidney beans in spiced yogurt and dry fruits), Chha Gosht (tender lamb simmered in gram flour and curd gravy), Maah ki Dal, and sweet meethe chawal flavored with saffron and raisins.', 'https://himachaltourism.gov.in/destination/chamba/'),
        (47, 4, 'Kinnaur', 'kinnaur', 'A land of myths bordering Tibet, Kinnaur is famed for the sacred 6,050-metre Kinner Kailash peak, dramatic river gorges carved by the Sutlej, and picturesque villages like Kalpa and Sangla with traditional slate-roofed wooden architecture and fragrant apple and walnut orchards.', 'Enjoy authentic tribal Kinnauri cuisine: Ogla and Phafra (wholesome buckwheat rotis) with homemade churned butter, red rice with rajma, dry apple and apricot preparations, and traditional local fruit wines.', 'https://himachaltourism.gov.in/destination/kinnaur/'),
        (48, 4, 'Mandi', 'mandi', 'Known as the "Varanasi of the Hills", Mandi is an ancient sacred hub along the Beas River home to over 81 historic carved stone Shiva temples. The district encompasses the mystical high-altitude Prashar Lake at 2,730 m with its floating island and three-tiered pagoda temple, and the sacred multi-faith lake of Rewalsar revered by Buddhists, Hindus, and Sikhs.', 'Relish the famous Mandyali Dham feast: Sepu Badi (urad dal dumplings boiled, fried, and slow-cooked in a tangy spinach and curd gravy), Kaddu ka Khatta, Mah ki dal, and Jhol.', 'https://himachaltourism.gov.in/destination/mandi/'),
        (49, 4, 'Solan', 'solan', 'Known as the "Mushroom City of India", Solan is a picturesque gateway district in the lower Shivalik hills. It is home to the historic Kalka-Shimla Toy Train (a UNESCO World Heritage railway), the ancient Shoolini Mata Temple, the cantonment hill station of Kasauli with its colonial Christ Church, and Mohan Shakti Heritage Park.', 'Savour traditional Himachali food: Siddu with ghee, lushun ki chutney, poppy seed halwa, sweet and spicy roadside corn, and fresh locally grown button and oyster mushroom curries.', 'https://himachaltourism.gov.in/destination/solan/'),
        (50, 4, 'Sirmaur', 'sirmaur', 'A scenic southern district bordering Uttarakhand, Sirmaur is cradled by the Giri and Yamuna rivers. It features Renuka Lake—Himachal Pradesh’s largest natural water body shaped like a reclining woman—the historic royal capital of Nahan, the fossil park at Suketi, and panoramic views from Churdhar Peak (3,647 m).', 'Try rustic Sirmauri mountain recipes: Patande (thin wheat pancakes known as the crepes of Himachal), Rott (thick sweet baked wheat bread offered as auspicious food), and local black lentil madra.', 'https://himachaltourism.gov.in/destination/sirmaur/'),
        (51, 4, 'Bilaspur', 'himachal-pradesh-bilaspur', 'Situated in the Sutlej River valley, Bilaspur is famous for the vast Gobind Sagar Lake created by the monumental Bhakra Dam—one of the highest straight gravity dams in the world. The district is also renowned for the hilltop Naina Devi Temple, water sports on the lake, and the historic town of Bilaspur.', 'Enjoy freshly prepared freshwater river fish fry from Gobind Sagar, makki di roti with sarson ka saag, rajma madra, and traditional hill kheer.', 'https://himachaltourism.gov.in/destination/bilaspur/'),
        (52, 4, 'Hamirpur', 'hamirpur', 'A central sub-mountainous district surrounded by pine forests and rolling ridges. It is celebrated for the historic Sujanpur Tira fort with its 18th-century Katoch dynasty wall murals, the widely revered cave shrine of Baba Balak Nath at Deotsidh, and peaceful rural temples.', 'Taste traditional Hamirpuri specialties: Bhey (spicy lotus stem sautéed with gram flour and coriander), spiced Babru, urad dal madra, and kachori.', 'https://himachaltourism.gov.in/destination/hamirpur/'),
        (53, 4, 'Una', 'una', 'The southwestern gateway to Himachal Pradesh in the Swan River valley, Una is renowned for the holy Chintpurni Devi Temple (one of the 51 sacred Shakti Peethas where Goddess Sati’s feet fell), Dera Baba Barbhag Singh, and the quiet foothills of the Shivaliks.', 'Sample sacred temple prasad: desi ghee boondi laddoos, rich kadhi chawal flavored with fenugreek and mustard seeds, and freshly roasted river corn.', 'https://himachaltourism.gov.in/destination/una/'),
    ]
    db.executemany('''INSERT OR IGNORE INTO districts
        (id,region_id,name,slug,description,food_notes,source_url) VALUES (?,?,?,?,?,?,?)''', districts)

    source_file = Path(__file__).with_name('data') / 'india-states-districts.json'
    if source_file.exists():
        existing_slugs = {row[0] for row in db.execute('SELECT slug FROM districts')}
        existing_names = {(row[0], row[1].lower()) for row in db.execute('SELECT region_id, name FROM districts')}
        next_id = db.execute('SELECT COALESCE(MAX(id), 0) + 1 FROM districts').fetchone()[0]
        region_sources = {row[0]: row[1] for row in db.execute('SELECT id, source_url FROM regions')}
        official_directory = json.loads(source_file.read_text(encoding='utf-8'))
        region_ids = {row[0].lower(): row[1] for row in db.execute('SELECT name, id FROM regions')}
        region_slugs = {row[0]: row[1] for row in db.execute('SELECT id, slug FROM regions')}
        for entry in official_directory:
            region_id = region_ids.get(entry.get('state', '').lower())
            if not region_id:
                continue
            for name in entry.get('districts', []):
                slug = name.lower().replace(' & ', '-').replace('&', '-').replace(' ', '-').replace("'", '')
                if (region_id, name.lower()) in existing_names:
                    continue
                if slug in existing_slugs:
                    slug = f'{region_slugs[region_id]}-{slug}'
                db.execute('''INSERT INTO districts
                    (id, region_id, name, slug, description, food_notes, source_url)
                    VALUES (?,?,?,?,?,?,?)''', (next_id, region_id, name, slug,
                    f'{name} district directory entry. Destination coverage is being expanded and reviewed.',
                    'Local food notes will be added with verified editorial sources.', region_sources[region_id]))
                existing_slugs.add(slug)
                existing_names.add((region_id, name.lower()))
                next_id += 1

