        (33, 'Garia Puja', 'The premier spring harvest festival celebrated by the indigenous Tripuri, Reang and Jamatia communities. A sacred bamboo pole representing Lord Garia is worshipped with choral songs, community feasts, and the energetic traditional Garia dance performed from house to house.', 'fixed', 'https://tripuratourism.gov.in/', [('tripura', 'west-tripura'), ('tripura', 'gomati')], [4]),
        (34, 'Diwali Mela at Tripura Sundari Temple', 'The legendary Festival of Lights at Matabari in Udaipur, drawing hundreds of thousands of pilgrims. The entire 500-year-old temple complex and the sacred Kalyan Sagar lake are illuminated with countless earthen diyas, marked by holy dips and grand fairs.', 'lunar', 'https://tripuratourism.gov.in/', [('tripura', 'gomati')], [10, 11]),
        (35, 'Orange & Tourism Festival, Jampui Hills', 'A picturesque winter celebration in the highest hill range of Tripura, celebrating the orange harvest with colourful Mizo Cheraw (bamboo) dances, acoustic music performances, trekking, and panoramic views of the clouds.', 'fixed', 'https://tripuratourism.gov.in/', [('tripura', 'north-tripura')], [11, 12]),
        (36, 'Pous Sankranti Mela at Tirthamukh', 'An ancient sacred river-confluence festival held on Makar Sankranti at Dumboor Lake, where the Raima and Sarma rivers unite. Devotees take a holy dawn dip in the sacred waters and perform ancestral rituals amidst a colourful tribal fair.', 'fixed', 'https://tripuratourism.gov.in/', [('tripura', 'dhalai')], [1]),
        (37, 'Kullu Dussehra', 'An extraordinary century-old international festival at Dhalpur Maidan in Kullu. When Dussehra celebrations end across India, Kullu\'s celebrations begin: over 200 village deities (Devtas) arrive in grand wooden raths to pay homage to Lord Raghunath amidst joyful hill trumpet fanfares.', 'lunar', 'https://himachaltourism.gov.in/', [('himachal-pradesh', 'kullu')], [10]),
